package testhelpers

import (
	"errors"
	"fmt"
	"os"
	"runtime"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestCaptureStdout_CapturesOutput(t *testing.T) {
	out := CaptureStdout(t, func() { fmt.Print("hello") })
	assert.Equal(t, "hello", out)
}

func TestCaptureStdoutE_CapturesOutput(t *testing.T) {
	out := CaptureStdoutE(t, func() error {
		fmt.Print("hello")
		return nil
	})
	assert.Equal(t, "hello", out)
}

func TestCaptureStderr_CapturesOutput(t *testing.T) {
	out := CaptureStderr(t, func() { fmt.Fprint(os.Stderr, "hello") })
	assert.Equal(t, "hello", out)
}

// countOpenFDs returns the number of open file descriptors for the
// current process via /dev/fd (present on Linux and macOS, the two
// platforms this suite runs tests on). Skips rather than fails if /dev/fd
// is unavailable, since this is a portability probe, not the property
// under test.
func countOpenFDs(t *testing.T) int {
	t.Helper()
	entries, err := os.ReadDir("/dev/fd")
	if err != nil {
		t.Skipf("cannot count open file descriptors on this platform: %v", err)
	}
	return len(entries)
}

// TestCapture_DrainGoroutineExitsOnFnError guards against the drain
// goroutine blocking on ReadFrom forever when fn returns an error rather
// than panicking or calling Goexit. Exercises the unexported capture
// directly (white-box) so the returned error can be inspected without
// require.NoError inside this test itself invoking FailNow.
func TestCapture_DrainGoroutineExitsOnFnError(t *testing.T) {
	baseline := runtime.NumGoroutine()

	out, err := capture(t, &os.Stdout, func() error {
		return errors.New("boom")
	})

	assert.Equal(t, "", out)
	require.EqualError(t, err, "boom")

	// Poll by hand rather than require.Eventually: Eventually runs the
	// condition from its own background goroutine, which is itself
	// counted by runtime.NumGoroutine() and would permanently offset the
	// comparison against a baseline taken before it started.
	deadline := time.Now().Add(2 * time.Second)
	for {
		if runtime.NumGoroutine() <= baseline {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf(
				"drain goroutine must exit after fn returns an error, not block on ReadFrom until the process exits (goroutines: %d, baseline: %d)",
				runtime.NumGoroutine(), baseline)
		}
		time.Sleep(10 * time.Millisecond)
	}
}

// TestCapture_PanicStillClosesReadEndAndJoinsDrain guards the panic path:
// a panic inside fn must still restore *target, close both pipe ends, and
// join the drain goroutine before capture's deferred cleanup re-panics.
func TestCapture_PanicStillClosesReadEndAndJoinsDrain(t *testing.T) {
	baseline := countOpenFDs(t)

	func() {
		defer func() {
			p := recover()
			require.Equal(t, "boom", p)
		}()
		_, _ = capture(t, &os.Stdout, func() error {
			panic("boom")
		})
	}()

	got := countOpenFDs(t)
	assert.Equal(t, baseline, got, "read end of the capture pipe leaked across a panic in fn")
}

package testhelpers

import (
	"errors"
	"os"
	"os/exec"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

// goexitHelperEnv gates TestGoexitHelperProcess so a normal `go test`
// run treats it as a no-op skip, and only the subprocess
// TestCapture_GoexitInFnDoesNotHang spawns actually exercises it.
const goexitHelperEnv = "ETHOS_TESTHELPERS_GOEXIT_HELPER"

// TestCapture_GoexitInFnDoesNotHang is the regression guard for PR #509's
// J2 finding: fn calling t.Fatal or a require.* assertion (both
// runtime.Goexit, not a panic) must not skip capture's cleanup and leave
// the drain goroutine blocked on ReadFrom forever.
//
// This property cannot be proven in-process without permanently failing
// this test's own package: testing.T's FailNow-family methods must be
// called from the test's own goroutine (a spawned goroutine cannot call
// them per the testing package's documented contract), and a raw
// runtime.Goexit() called directly on this test's own goroutine is itself
// reported by the testing package as a failure ("test executed panic(nil)
// or runtime.Goexit"), not something this test could recover from and
// keep the suite green. So this spawns a real subprocess to run
// TestGoexitHelperProcess, which deliberately fails via require.NoError
// (Goexit) from inside CaptureStdout's fn. The property under test is
// that the subprocess exits promptly rather than hanging -- not its exit
// code, which is always 1 because of the deliberate failure.
//
// Falsified pre-fix: reverting capture's cleanup to run only in the
// straight-line path after "fnErr = fn()" returns -- the shape every one
// of the eight independently-duplicated helpers PR #509's review found
// had -- makes the subprocess hang past the deadline below. The drain
// goroutine blocks on buf.ReadFrom(r) forever because nothing ever closes
// the pipe's write end when fn exits via Goexit instead of a normal
// return; confirmed by temporarily reverting capture() to that shape and
// observing this test time out and kill the subprocess rather than
// observing it exit within the 2s of real work it does.
func TestCapture_GoexitInFnDoesNotHang(t *testing.T) {
	cmd := exec.Command(os.Args[0], "-test.run=^TestGoexitHelperProcess$", "-test.v") //nolint:gosec // re-invoking this package's own test binary, a standard Go subprocess-test idiom (cf. os/exec's TestHelperProcess).
	cmd.Env = append(os.Environ(), goexitHelperEnv+"=1")

	done := make(chan error, 1)
	require.NoError(t, cmd.Start())
	go func() { done <- cmd.Wait() }()

	select {
	case <-done:
		// Expected to exit with status 1 -- TestGoexitHelperProcess
		// deliberately fails. Only the prompt exit matters here.
	case <-time.After(10 * time.Second):
		_ = cmd.Process.Kill()
		t.Fatal("subprocess did not exit within 10s: Goexit inside fn left the drain goroutine blocked on the pipe")
	}
}

// TestGoexitHelperProcess is not a real test of this package: it is the
// subprocess entry point TestCapture_GoexitInFnDoesNotHang spawns. A
// direct `go test` run leaves goexitHelperEnv unset, so it skips
// immediately and contributes nothing to a normal run of this suite.
func TestGoexitHelperProcess(t *testing.T) {
	if os.Getenv(goexitHelperEnv) != "1" {
		t.Skip("subprocess entry point for TestCapture_GoexitInFnDoesNotHang")
	}
	CaptureStdout(t, func() {
		require.NoError(t, errors.New("deliberate failure to exercise the Goexit path"))
	})
}

